-- =====================================================================
-- V22: Danh muc dinh duong co khuyen nghi lam sang
-- Additive: chi tao bang moi. Gia tri dinh duong KHONG luu o day ma doc tu
-- nutrition_foods (V21) qua nutrition_food_id, nen khong bi lech so lieu.
-- =====================================================================

CREATE TABLE nutrition_food_groups (
    id VARCHAR(40) PRIMARY KEY,
    slug VARCHAR(60) NOT NULL UNIQUE,
    name VARCHAR(120) NOT NULL,
    description VARCHAR(500),
    dietary_pattern VARCHAR(20) NOT NULL
        CHECK (dietary_pattern IN ('PRIORITIZE', 'LIMIT', 'CAUTION', 'BALANCED')),
    icon VARCHAR(40),
    image_url VARCHAR(500),
    display_order INTEGER NOT NULL,
    created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ,
    created_by VARCHAR(255), updated_by VARCHAR(255)
);

CREATE TABLE nutrition_evidence_sources (
    id VARCHAR(60) PRIMARY KEY,
    title VARCHAR(500) NOT NULL,
    source_type VARCHAR(30) NOT NULL
        CHECK (source_type IN ('GUIDELINE', 'SYSTEMATIC_REVIEW', 'META_ANALYSIS', 'RCT', 'OTHER')),
    authors VARCHAR(300),
    journal VARCHAR(200),
    publication_year INTEGER,
    url VARCHAR(500),
    summary VARCHAR(1000),
    created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ,
    created_by VARCHAR(255), updated_by VARCHAR(255)
);

CREATE TABLE nutrition_guidance_foods (
    id VARCHAR(60) PRIMARY KEY,
    group_id VARCHAR(40) NOT NULL REFERENCES nutrition_food_groups(id),
    nutrition_food_id BIGINT NOT NULL REFERENCES nutrition_foods(id),
    food_name VARCHAR(120) NOT NULL,
    food_name_specific VARCHAR(160) NOT NULL,
    description VARCHAR(1000),
    guidance VARCHAR(20) NOT NULL CHECK (guidance IN ('PRIORITIZE', 'LIMIT', 'CAUTION')),
    guidance_title VARCHAR(200) NOT NULL,
    guidance_reason VARCHAR(1000) NOT NULL,
    cardiovascular_context VARCHAR(1000),
    af_context VARCHAR(1000),
    medication_context VARCHAR(1000),
    highlight_nutrient_codes VARCHAR(200) NOT NULL,
    image_url VARCHAR(500),
    search_text VARCHAR(2000) NOT NULL,
    display_order INTEGER NOT NULL,
    created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ,
    created_by VARCHAR(255), updated_by VARCHAR(255)
);

COMMENT ON COLUMN nutrition_guidance_foods.highlight_nutrient_codes IS 'Ma chat dinh duong noi bat, cach nhau bang dau phay, dung thu tu hien thi';
COMMENT ON COLUMN nutrition_guidance_foods.search_text IS 'Chu thuong, bo dau tieng Viet: ten mon + ten cu the + ten nguon + mo ta';

CREATE INDEX idx_nutrition_guidance_food_group ON nutrition_guidance_foods (group_id, display_order);
CREATE INDEX idx_nutrition_guidance_food_name ON nutrition_guidance_foods (food_name);
CREATE INDEX idx_nutrition_guidance_food_source ON nutrition_guidance_foods (nutrition_food_id);

CREATE TABLE nutrition_guidance_food_evidence (
    guidance_food_id VARCHAR(60) NOT NULL REFERENCES nutrition_guidance_foods(id) ON DELETE CASCADE,
    evidence_source_id VARCHAR(60) NOT NULL REFERENCES nutrition_evidence_sources(id),
    display_order INTEGER NOT NULL,
    PRIMARY KEY (guidance_food_id, evidence_source_id)
);

CREATE INDEX idx_nutrition_guidance_evidence_source ON nutrition_guidance_food_evidence (evidence_source_id);

